def count_fully_disinfected_aliens():
    n, m = map(int, input().split())
    h = list(map(int, input().split()))

    remaining_disinfectant = m
    count = 0

    for hands in h:
        if remaining_disinfectant >= hands:
            count += 1
            remaining_disinfectant -= hands
        else:
            break

    print(count)
